import 'vue-select/dist/vue-select.css';
import bus from '~/plugins/bus';
import vSelect from 'vue-select';
import Datepicker from 'vuejs-datepicker';
import Mixin from '~/mixins/Mixin';
export default {
  name: 'DataDiriEmployee',
  mixins: [Mixin],
  data: function data() {
    return {
      fotoUploaded: ''
    };
  },
  props: {
    dataDiri: {
      type: Object,
      required: true
    },
    agama: {
      type: Array,
      required: true
    },
    statusPegawai: {
      type: Array,
      required: true
    },
    statusPerkawinan: {
      type: Array,
      required: true
    },
    jabatan: {
      type: Array,
      required: true
    },
    jenisJabatan: {
      type: Array,
      required: true
    },
    unitKerja: {
      type: Array,
      required: true
    },
    privilege: {
      type: Array,
      required: true
    },
    currentPrivilege: {
      type: String,
      required: true
    },
    education: {
      type: Array,
      required: true
    },
    options: {
      type: Object,
      required: false
    },
    golonganList: {
      type: Array,
      required: true
    }
  },
  components: {
    vSelect: vSelect,
    Datepicker: Datepicker
  },
  methods: {
    handlePictureUpload: function handlePictureUpload() {
      var pictureUploaded = this.$refs.pictureUpload.files[0];
      var pictureData = {
        file: pictureUploaded,
        name: this.generatePictureName(pictureUploaded)
      };
      bus.$emit('set-picture-upload', pictureData);
    },
    generatePictureName: function generatePictureName(file) {
      var employeeId = this.$store.state.employeeId;
      var employeeNIP = this.dataDiri.nip;
      var ext = file.name.substr(file.name.lastIndexOf('.') + 1);
      return "".concat(employeeId, "-").concat(employeeNIP, ".").concat(ext);
    }
  }
};